// slg: todo/laws.slg:33:1 todo.laws.stored_under_its_number law
// @why a task is stored under its own number
function storedUnderItsNumber(
  t: Trace<
    World,
    Extract<
      Event,
      {
        readonly rule: "add" | "done" | "reopen" | "rename" | "remove" | "clear";
      }
    >
  >,
): boolean {
  return t.states.every((w_) => [...w_.tasks.keys()].every((k) => at(w_.tasks, k).no === k));
}

